import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import humanTime from 'flarum/common/helpers/humanTime';
import { call } from '../../common/api';
import { formatScore } from '../../common/format';
import { avatar } from './Person';
import { t } from '../t';
// Module-level: a widget host may remount the widget; the list survives it.
const cache = {};

/** The latest crowns, for a sidebar. */
export default class WidgetBody extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    if (!cache[this.attrs.limit]) {
      call('GET', '/crowns', undefined, {
        limit: this.attrs.limit
      }).then(r => {
        cache[this.attrs.limit] = r.data;
        m.redraw();
      });
    }
  }
  view() {
    const crowns = cache[this.attrs.limit];
    if (!crowns) return m(LoadingIndicator, {
      size: "small",
      display: "block"
    });
    if (!crowns.length) return m("p", {
      className: "InsertCoinWidget-empty"
    }, t('home.crowns_empty'));
    return m("ul", {
      className: "InsertCoinWidget InsertCoinCrowns"
    }, crowns.map(c => m("li", {
      className: "InsertCoinCrowns-row"
    }, avatar(c.user, true), m("div", {
      className: "InsertCoinCrowns-text"
    }, m("div", null, m("b", null, c.user.displayName), " \xB7 ", m(Link, {
      href: app.route('insert-coin.game', {
        slug: c.game.slug
      })
    }, c.game.title)), m("div", {
      className: "InsertCoinCrowns-meta"
    }, formatScore(c.score, c.game.scoreLabel), " \xB7 ", humanTime(new Date(c.at)))))));
  }
}
flarum.reg.add('ernestdefoe-insert-coin', 'forum/components/WidgetBody', WidgetBody);