import app from 'flarum/common/app';
const url = path => app.forum.attribute('apiUrl') + '/insert-coin' + path;

/** `quiet`: the caller shows the error itself, so no alert pops up as well. */
export function call(method, path, body, params, quiet = false) {
  return app.request({
    method,
    url: url(path),
    body,
    params,
    errorHandler: quiet ? error => {
      throw error;
    } : undefined
  });
}
const data = p => p.then(r => r.data);
export const home = () => data(call('GET', ''));
export const showGame = slug => data(call('GET', `/games/${slug}`));
export const board = (gameId, period, offset = 0, limit = 10) => data(call('GET', `/games/${gameId}/scores`, undefined, {
  period,
  offset,
  limit
}));
export const startSession = gameId => data(call('POST', `/games/${gameId}/sessions`));
export const submitScore = (session, score) => data(call('POST', `/sessions/${session.id}/score`, {
  token: session.token,
  score
}, undefined, true));
export const profile = userId => data(call('GET', `/users/${userId}`));
export const queue = (offset = 0) => call('GET', '/queue', undefined, {
  offset
});
export const approve = id => call('POST', `/scores/${id}/approve`);
export const removeScore = id => call('DELETE', `/scores/${id}`);
export const wipeGame = (gameId, userId) => call('DELETE', `/games/${gameId}/scores`, undefined, userId ? {
  user: userId
} : undefined);
export const wipeUser = userId => call('DELETE', `/users/${userId}/scores`);
export const ban = (userId, wipe) => call('POST', `/users/${userId}/ban`, {
  wipe
});
export const unban = userId => call('DELETE', `/users/${userId}/ban`);
flarum.reg.add('ernestdefoe-insert-coin', 'common/api', { call: call,home: home,showGame: showGame,board: board,startSession: startSession,submitScore: submitScore,profile: profile,queue: queue,approve: approve,removeScore: removeScore,wipeGame: wipeGame,wipeUser: wipeUser,ban: ban,unban: unban, });